import type { AdNetworkAdapter } from "./registry.js";
export const simulatedAdapter:AdNetworkAdapter={id:"simulated",async mount(unit,container,_ctx,signal){const delay=Number(unit.simulated_delay_ms??0); await new Promise<void>((res,rej)=>{const t=setTimeout(res,delay); signal.addEventListener("abort",()=>{clearTimeout(t); rej(new DOMException("aborted","AbortError"));},{once:true});}); const outcome=String(unit.simulated_outcome??"filled") as any; if(outcome==="error") throw new Error("simulated error"); if(outcome==="timeout") return new Promise(()=>{}); if(outcome==="filled") container.innerHTML=`<div class="ad-runner-simulated">${unit.text??unit.format??"Simulated ad filled"}</div>`; return {outcome,reason:`simulated ${outcome}`,renderedAt:Date.now()};},async destroy(_u,c){c.remove();}};
